<script setup lang="ts">
import {localize} from './localization';

import {computed,inject,ref,watch,nextTick} from 'vue';
import {useSession} from './store';
import {seamReports} from '../../../packages/manufacturing/seams';
import type {Seam} from '../../../packages/schema/index';
const advanced=inject('advancedMode',ref(false));
const props=defineProps<{language:'zh'|'en';targetId?:string}>();const store=useSession(),zh=computed(()=>props.language==='zh'),name=ref('Seam'),a=ref(''),b=ref(''),ease=ref(0),tolerance=ref(1),reverse=ref(true),locked=ref(false),startA=ref(0),endA=ref(1),startB=ref(0),endB=ref(1);
watch(()=>props.targetId,()=>void nextTick(()=>document.querySelector('.seam-row.active')?.scrollIntoView({block:'nearest'})));
const notchCount=ref(3),notchDepth=ref(3);
async function notches(seamId:string){const p=store.data.project;if(p)await store.run(()=>window.fpcad.pairNotches(p.id,p.revision,seamId,notchCount.value,notchDepth.value));}
const edges=computed(()=>store.data.project?.pieces.flatMap(p=>p.nodes.slice(0,p.closed?undefined:-1).map((n,i)=>({key:`${p.id}:${n.id}`,pieceId:p.id,nodeId:n.id,endNodeId:p.nodes[(i+1)%p.nodes.length].id,label:`${p.name} / ${i+1} → ${(i+1)%p.nodes.length+1}`})))??[]);
const reports=computed(()=>new Map(store.data.project?seamReports(store.data.project,store.data.geometry).map(r=>[r.id,r]):[]));
const report=(seam:Seam)=>reports.value.get(seam.id)!;
async function put(seam:Seam){const p=store.data.project;if(p)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'seam.put',seam:JSON.parse(JSON.stringify(seam))}));}
async function add(){const ea=edges.value.find(e=>e.key===a.value),eb=edges.value.find(e=>e.key===b.value);if(!ea||!eb||a.value===b.value)return;const side=(e:typeof ea,start:number,end:number,reverse:boolean)=>({pieceId:e.pieceId,nodeId:e.nodeId,endNodeId:e.endNodeId,start,end,reverse});await put({id:crypto.randomUUID(),name:name.value,a:side(ea,startA.value,endA.value,false),b:side(eb,startB.value,endB.value,reverse.value),expectedEaseMm:ease.value,toleranceMm:tolerance.value,locked:locked.value});}
async function remove(id:string){const p=store.data.project;if(p)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'seam.delete',seamId:id}));}
</script>
<template><div class="seams-panel"><p>{{zh?'配对的是无缝份的缝线边。残差 = |A 长度 − B 长度 − 声明吃量|；修改边界后会重新检查，拓扑变化会使引用失效。':localize('Pairs seam edges, excluding allowance. Residual = |A length − B length − declared ease|. Edits revalidate; topology changes invalidate references.')}}</p>
 <div class="options"><label>{{zh?'接缝名称':localize('Name')}}<input v-model="name" maxlength="120"></label><label>A<select v-model="a"><option value="">—</option><option v-for="e in edges" :key="e.key" :value="e.key">{{e.label}}</option></select></label><label>B<select v-model="b"><option value="">—</option><option v-for="e in edges" :key="e.key" :value="e.key">{{e.label}}</option></select></label><label v-if="advanced">A {{zh?'起止':localize('range')}}<input v-model.number="startA" type="number" min="0" max="1" step=".05"><input v-model.number="endA" type="number" min="0" max="1" step=".05"></label><label v-if="advanced">B {{zh?'起止':localize('range')}}<input v-model.number="startB" type="number" min="0" max="1" step=".05"><input v-model.number="endB" type="number" min="0" max="1" step=".05"></label><label>{{zh?'吃量 mm':localize('Ease mm')}}<input v-model.number="ease" type="number" step=".1"></label><label>{{zh?'公差 mm':localize('Tolerance mm')}}<input v-model.number="tolerance" type="number" min="0" step=".1"></label><label><input v-model="reverse" type="checkbox">{{zh?'B 反向':localize('Reverse B')}}</label><label><input v-model="locked" type="checkbox">{{zh?'锁定接缝':localize('Lock seam')}}</label><button :disabled="!a||!b||a===b||store.busy" @click="add">{{zh?'建立接缝':localize('Link seam')}}</button></div>
<div class="options"><label>{{zh?'配对剪口数量':localize('Paired notch count')}}<input v-model.number="notchCount" type="number" min="1" max="20"></label><label>{{zh?'剪口深度 mm':localize('Notch depth mm')}}<input v-model.number="notchDepth" type="number" min=".1" max="100"></label></div>
 <div v-for="s in store.data.project?.seams??[]" :key="s.id"  :class="['seam-row',{active:s.id===targetId}]"><label>{{zh?'接缝名称':localize('Seam name')}}<input :value="s.name" :disabled="store.busy||s.locked" maxlength="120" @change="put({...s,name:($event.target as HTMLInputElement).value})"></label><div class="two-col"><label>{{zh?'吃势 mm':localize('Ease mm')}}<input type="number" :value="s.expectedEaseMm" :disabled="store.busy||s.locked" @change="put({...s,expectedEaseMm:Number(($event.target as HTMLInputElement).value)})"></label><label>{{zh?'容差 mm':localize('Tolerance mm')}}<input type="number" min="0" :value="s.toleranceMm" :disabled="store.busy||s.locked" @change="put({...s,toleranceMm:Number(($event.target as HTMLInputElement).value)})"></label></div><span>A {{report(s).aMm.toFixed(3)}} mm · B {{report(s).bMm.toFixed(3)}} mm · e {{s.expectedEaseMm}} mm · r {{report(s).residualMm.toFixed(3)}} mm / {{report(s).toleranceMm}} mm</span><b :class="{error:report(s).status!=='valid'}">{{report(s).status==='stale'?(zh?'引用失效':localize('Stale references')):report(s).status==='mismatch'?(zh?'不匹配':localize('Mismatch')):(zh?'长度匹配':localize('Lengths match'))}}</b><button :disabled="store.busy" @click="put({...s,locked:!s.locked})">{{s.locked?(zh?'解锁':localize('Unlock')):(zh?'锁定':localize('Lock'))}}</button><button :disabled="store.busy||report(s).status!=='valid'" @click="notches(s.id)">{{zh?'生成配对剪口':localize('Generate paired notches')}}</button><button :disabled="store.busy||s.locked" @click="remove(s.id)">{{zh?'解除关联':localize('Unlink')}}</button></div>
</div></template>
<style scoped>.seams-panel{padding:12px;font-size:12px}.options{display:flex;gap:10px;flex-wrap:wrap;align-items:end}.options label{display:block}.options input[type=number]{width:80px;display:block}.options input:not([type]),.options select{max-width:160px}.seam-row{display:flex;align-items:center;gap:12px;margin:12px 0;flex-wrap:wrap}.error{color:var(--danger)}.seams-panel p{line-height:1.5}</style>

<style scoped>.seam-row.active{outline:1px solid var(--accent)}.seam-row label{font-size:11px;width:100%}.seam-row .two-col{width:100%}</style>
